from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    cleaned = paren_string.replace(" ", "")
    groups = []
    count = 0
    start = 0
    for i, char in enumerate(cleaned):
        if char == '(':
            count += 1
        elif char == ')':
            count -= 1
        if count == 0:
            groups.append(cleaned[start:i+1])
            start = i + 1
    return groups

