import math

def find_zero(xs: list):
    x = 0.0
    tolerance = 1e-7
    max_iter = 100
    for _ in range(max_iter):
        f = poly(xs, x)
        if abs(f) < tolerance:
            return x
        f_prime = 0.0
        for i in range(1, len(xs)):
            f_prime += xs[i] * i * math.pow(x, i-1)
        if abs(f_prime) < tolerance:
            break
        x = x - f / f_prime
    return x

